static rsRetVal readResponseLn ( wrkrInstanceData_t * pWrkrData , char * pLn , size_t lenLn , size_t * const __restrict__ respLen ) { DEFiRet ; size_t i = 0 ; char c ; assert ( pWrkrData != NULL ) ; assert ( pLn != NULL ) ; { if ( c == '\n' ) { break ; } if ( i < ( lenLn - 1 ) ) { pLn [ i ++ ] = c ; } } 1 ; DBGPRINTF ( "smtp server response: %s\n" , pLn ) ; finalize_it pLn [ i ] = '\0' ; * respLen = i ; RETiRet ; } 